<?php
namespace App\Http\Controllers;
use App\Models\Branch;use Illuminate\Http\Request;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class BranchController extends Controller{public function index(){return view('branches.index',['items'=>Branch::withCount('inventories')->latest()->paginate(10)]);}public function create(){return view('branches.form',['item'=>new Branch]);}public function store(Request $r){return $this->save($r,new Branch);}public function edit(Branch $branch){return view('branches.form',['item'=>$branch]);}public function update(Request $r,Branch $branch){return $this->save($r,$branch);}public function destroy(Branch $branch){$old=$branch->toArray();$branch->update(['is_active'=>false]);$this->audit('branch.deleted',$branch,$old,$branch->fresh()->toArray());return back()->with('success','Sede desactivada y conservada en el historial.');}private function save(Request $r,Branch $branch){$old=$branch->exists?$branch->toArray():null;$data=$r->validate(['name'=>['required','string','max:255',Rule::unique('branches')->ignore($branch->id)],'is_active'=>'nullable|boolean']);$data['slug']=Str::slug($data['name']);$data['is_active']=$r->boolean('is_active',true);$branch->fill($data)->save();$this->audit($old?'branch.updated':'branch.created',$branch,$old,$branch->fresh()->toArray());return redirect()->route('branches.index')->with('success','Sede guardada.');}}
